using System;using System.IO;using System.Threading;using System.Reflection;using System.Collections;using System.Collections.Generic;using System.Security.Cryptography;using System.Web.Script.Serialization;
public static class LiveClientReview{
 static BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static object P(object o,string n){return o.GetType().GetProperty(n,F).GetValue(o,null);}
 static object C(object o,string n,params object[] args){return o.GetType().GetMethod(n,F).Invoke(o,args);}
 public static int Main(string[] args){string target=Path.GetFullPath(args[0]),path=Path.GetFullPath(args[1]);int duration=int.Parse(args[2]);var r=new Dictionary<string,object>();object client=null;var samples=new List<object>();try{
  using(var h=SHA256.Create())using(var f=File.OpenRead(target))r["candidate_sha256"]=BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();var a=Assembly.LoadFrom(target);client=Activator.CreateInstance(a.GetType("WhiteDragon.ClientLink"));client.GetType().GetProperty("Enabled").SetValue(client,true,null);C(client,"Start");r["scope"]="Real OS UIAutomation callbacks and control polling from the current Windows client. No synthetic Observe calls, hook fixtures or chat text. Not native Codex lifecycle hooks.";r["started_utc"]=DateTime.UtcNow.ToString("o");DateTime end=DateTime.UtcNow.AddSeconds(duration);string previous=null;
  while(DateTime.UtcNow<end){object state=C(client,"State",DateTime.UtcNow);string status=state==null?null:(string)state.GetType().GetField("status").GetValue(state);if(status!=previous){samples.Add(new{utc=DateTime.UtcNow.ToString("o"),status=status});previous=status;}r["samples"]=samples;r["event_callbacks"]=P(client,"EventCallbacks");r["last_callback_utc"]=P(client,"LastCallbackUtc");var gate=client.GetType().GetField("gate",F).GetValue(client);lock(gate){r["real_state_events"]=new List<string[]>((IEnumerable<string[]>)client.GetType().GetField("RealStateEvents").GetValue(client));}r["description"]=P(client,"Description");File.WriteAllText(path,new JavaScriptSerializer().Serialize(r));Thread.Sleep(200);}
 }catch(Exception e){r["error"]=e.ToString();}finally{if(client!=null){C(client,"Dispose");for(int i=0;i<30&&!(bool)P(client,"WorkerStopped");i++)Thread.Sleep(100);r["worker_stopped"]=P(client,"WorkerStopped");}r["finished_utc"]=DateTime.UtcNow.ToString("o");File.WriteAllText(path,new JavaScriptSerializer().Serialize(r));}return r.ContainsKey("error")?1:0;}
}
